      "say": "Now lighten the load. Write down everything on your plate. Mark what truly matters this week. Notice what can be good enough. Then pick one thing to drop, delay, or ask for help with. If you're working long hours while in school, look at it honestly with an advisor or a manager. You get to choose what gives."
