      "k": "big",
      "h": "Plan one easy thing.",
      "sub": "Something with no work talk.",
      "say": "Think of one easy, low-cost thing you could do together this week. A walk, a meal, a game, or a drive. Say it out loud, and pick the day you will ask them.",
