      "say": "Here's a surprise a lot of people get. You know your hours and your rate, and the check is still smaller. Taxes and other deductions come out first, like health insurance or retirement. Your pay stub shows it all. Gross pay is what you earned. Net pay is what you keep. Check that the hours are right."
