      "say": "Credit follows you into leases, car loans, and sometimes job checks, so build it on purpose. Pay every bill on time. Autopay the minimum so you never miss one. Use a card only for what you can pay off in full. And check your credit reports at the official site, looking for anything you don't recognize."
