    "guide": "moving-back",
    "side": "you",
    "title": "Moving Back Home",
    "sideName": "For You",
    "mins": 4,
    "blurb": "For the young adult moving back home: this is a season, not a verdict, and it goes best with clear agreements and a plan.",
    "sources": [
     "pewparents"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "birch",
      "eyebrow": "When Life Changes",
      "h": "Moving Back Home",
      "sub": "For You",
      "say": "If you've moved back in with family, or you're about to, this is for you. Whatever brought you here, this can be a good season."
     },
     {
      "k": "big",
      "h": "This is common.",
      "sub": "And it can be a smart move.",
      "say": "Moving back home is common. More than half of eighteen to twenty four year olds live with a parent, and many people move out and back more than once. People come home to save money, to heal, to change direction, or to help family. It says nothing bad about you."
     },
     {
      "k": "words",
      "h": "What it can feel like",
      "items": [
       "Relief",
       "Embarrassment",
       "Like I am sixteen again",
       "Grateful and restless"
      ],
      "say": "It can bring a mix of feelings. Relief. Embarrassment, especially when friends post their new apartments. Feeling like you're sixteen again when someone asks where you're going. Grateful and restless in the same day. All of it is common."
     },
     {
      "k": "big",
      "h": "Two adults, one home.",
      "sub": "A new relationship to build.",
      "say": "Here's the shift. You're an adult living with family, and that's a new relationship. Old patterns may show up on both sides. You might slip into old roles too. You can be kind and still be an adult here, and you can ask to be treated like one."
     },
     {
      "k": "points",
      "h": "Agree on the basics early",
      "items": [
       [
        "Money",
        "Rent, groceries, or bills"
       ],
       [
        "Chores",
        "Who does what"
       ],
       [
        "Space and guests",
        "Privacy, quiet, visitors"
       ],
       [
        "How long",
        "A rough timeline"
       ]
      ],
      "say": "Have one honest talk early, before small things turn into arguments. Agree on money, whether that's rent, groceries, or a bill you cover. Chores. Space and guests, including privacy and quiet hours. And roughly how long, even if the answer is, let's check again in three months."
     },
     {
      "k": "big",
      "h": "Name your reason.",
      "sub": "A season with a purpose.",
      "say": "Take a minute for your own plan. Think about what you want this season at home to give you: savings, rest, a new job, school, healing, or time with family. Write one sentence that starts, while I am home, I am working toward, and one more that starts, and I will help by.",
      "beats": [
       "Take a minute for your own plan.",
       "Think about what you want this season at home to give you: savings, rest, a new job, school, healing, or time with family.",
       {
        "t": "Write one sentence that starts, while I am home, I am working toward, and one more that starts, and I will help by.",
        "w": 14
       }
      ]
     },
     {
      "k": "big",
      "h": "Keep your own rhythm.",
      "sub": "Places and people outside the house.",
      "say": "Keep your own rhythm while you're home. Work, school, or a search. Movement and sleep. A place that's yours outside the house, like a gym, a library, or a trail. And time with friends. When it feels like everyone else is ahead, compare yourself to where you were, not to their highlight reel."
     },
     {
      "k": "card",
      "title": "If it is more than a season",
      "body": "A low that lasts: a doctor or counselor. Not wanting to live: call or text 988. Danger: 911.",
      "say": "If a low mood, anxiety, or substance use came home with you, or it hasn't lifted, talk with a doctor or a counselor. If you ever think about not wanting to be alive, call or text nine eight eight, any time. If someone at home is hurting you, or you're in danger, call nine one one."
     },
     {
      "k": "big",
      "h": "A season, not a verdict.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "This is a season, not a verdict on your life. Use it well, and keep moving toward what's next. The full guide has more, whenever you want it."
     }
    ]
