      "say": "Here's where friendships grow now. Repeat. Go back to the same class, team, gym, group, or shift, so faces become familiar. Side by side. A shared activity takes the pressure off talking. Make the plan. Give it a what and a when, like tacos Thursday after work. And follow up. The second plan matters more than a perfect first one."
