      "say": "Many people hurt themselves to get through feelings that feel too big: anger, panic, shame, loneliness, or feeling nothing at all. It brings relief for a moment, and then shame, and a heavier secret. That doesn't make you bad or broken. It means you've been carrying a lot, mostly alone."
