   "helper": {
    "id": "br-g-military-helper",
    "guide": "military",
    "side": "helper",
    "title": "Joining the Military, and Military Life",
    "sideName": "For the Helper",
    "mins": 3,
    "blurb": "For a parent, partner, or friend of a young adult joining or serving: support the person, respect the choice.",
    "sources": [
     "monew"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "birch",
      "eyebrow": "When Life Changes",
      "h": "Joining the Military, and Military Life",
      "sub": "For the Helper",
      "say": "If someone you love is thinking about joining the military, or has already gone, this is for you. They're an adult making a big choice. Your steady support matters more than you may know."
     },
     {
      "k": "big",
      "h": "Their choice to make.",
      "sub": "Your questions can still help.",
      "say": "You may feel proud, worried, or both. It's tempting to talk them into it, or out of it. What helps more is curiosity. Ask what draws them to it. Help them gather questions, and if they want, go with them to meet a recruiter. Then trust them to choose."
     },
     {
      "k": "words",
      "h": "Words that help",
      "items": [
       "Tell me what draws you to this.",
       "I'm proud of you, and I'm here.",
       "You can tell me the hard parts too."
      ],
      "say": "Here are words that help. Tell me what draws you to this. I'm proud of you, and I'm here, whatever the day is like. And, you can tell me the hard parts too."
     },
     {
      "k": "big",
      "h": "Name what you see in them.",
      "sub": "One sentence.",
      "say": "Picture them on a long, hard day far from you. Think of one thing you have seen in them that will carry them through. Put it into one sentence that starts with: I have seen you, and say it quietly now.",
      "beats": [
       "Picture them on a long, hard day far from you.",
       "Think of one thing you have seen in them that will carry them through.",
       {
        "t": "Put it into one sentence that starts with: I have seen you, and say it quietly now.",
        "w": 12
       }
      ]
     },
     {
      "k": "points",
      "h": "While they serve",
      "items": [
       [
        "Learn the basics",
        "Mail, schedules, emergencies"
       ],
       [
        "Quiet is often normal",
        "Phones and schedules change"
       ],
       [
        "Warm, steady messages",
        "News from home, room for theirs"
       ],
       [
        "Skip the guilt",
        "For holidays or distance"
       ]
      ],
      "say": "While they serve, learn the basics: how to send mail, what their training looks like, and who to contact in an emergency. A quiet stretch is usually just a busy one. Keep your messages warm and steady, with news from home and room for theirs. And skip the guilt about missed holidays. They're likely missing home too."
     },
     {
      "k": "card",
      "title": "If they seem low",
      "body": "Military OneSource, for families too: 800-342-9647. Crisis: 988, then press 1.",
      "say": "If they seem low, keep in touch and ask directly how they're doing. Military OneSource helps families too, any time, at eight hundred, three four two, nine six four seven. If they ever talk about not wanting to be here, stay with them and help them call nine eight eight, then press one."
     },
     {
      "k": "big",
      "h": "Find your own people.",
      "sub": "Families serve too.",
      "say": "Letting someone you love go into service stirs a lot. Find your own people: other military families, Guard and Reserve family programs, or friends who will listen."
     },
     {
      "k": "big",
      "h": "Steady, from home.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "Your steady voice from home is part of what carries them. The full guide has more, whenever you want it."
     }
    ]
   }
